# application.yml
p199:
  # El fuente fija el siglo con MOVE 20 TO WKS-FEC-MIG-CC; aquí el pivote queda explícito.
  pivote-siglo: 2000
  # 206400-CATALOGO1565 está comentado: hoy la migración corre todos los días.
  validar-dia-migracion: false

// ---------------------------------------------------------------------------
@Bean
Job migracionCaptacion(JobRepository repo, Step fechaProceso, Step catalogos,
                       Step diaMigracion, Step migra, Step totales) {
    return new JobBuilder("S151P199", repo)
            .start(fechaProceso)              // 204000-LIBRERIAS
            .next(catalogos)                  // 206200-CATALOGO6
            .next(diaMigracion)               // 206400-CATALOGO1565, desactivado por propiedad
                .on("NO_MIGRACION").end()     // equivalente a W88-NO-MIGRACION y 602000-TERMINA
            .from(diaMigracion).on("*").to(migra)
            .next(totales)                    // 480000-GUARDA-TOTALES
            .end().build();
}

static LocalDate fechaMigracion(String aammdd, int pivoteSiglo) {   // WKS-FECPRO-6D
    return LocalDate.parse(aammdd, new DateTimeFormatterBuilder()
            .appendValueReduced(ChronoField.YEAR, 2, 2, pivoteSiglo)
            .appendPattern("MMdd").toFormatter());
}

@Component
@RequiredArgsConstructor
class FechaMigracionTasklet implements Tasklet {

    private final ControlS151Client control;   // CONSISDIA IN S151-L001

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        JobParameters p = ctx.getStepContext().getStepExecution().getJobParameters();
        String sistema = p.getString("sistema");                  // W77-PARAMETRO

        SistemaDia dia = control.consisdia(sistema, 1)
                .orElseThrow(() -> new ProcesoAbortadoException(
                        "NO PUEDO OBTENER FECHA DE PROCESO"));   // el fuente no se detiene aquí

        // TASKVALUE > 0 al lanzar el programa sustituye la fecha de la librería de control.
        LocalDate fecha = Optional.ofNullable(p.getLocalDate("fechaReproceso"))
                .orElse(dia.fecPro());
        ctx.getStepContext().getStepExecution().getJobExecution().getExecutionContext()
           .put("fechaProceso", fecha);
        ctx.getStepContext().getStepExecution().getJobExecution().getExecutionContext()
           .put("packMovs", dia.nomPacMov());
        return RepeatStatus.FINISHED;
    }
}

@Component
@RequiredArgsConstructor
class CatalogoClavesMigracion {

    private static final Set<Integer> APLICA = Set.of(4, 5, 6);   // p199.catalogo6.selector-campo14
    private final CatalogoEstructuraClient s080;                   // L710_CONSUL_DETALLE IN S080L710
    private Map<Integer, ClaveMigracion> claves;

    @PostConstruct
    void carga() {
        claves = s080.recorre(6, 2, Map.of("llave2", 500))           // paginado de 10 en 10
                .filter(d -> APLICA.contains(d.campo(14)))
                .collect(Collectors.toMap(d -> d.campo(1),
                        d -> new ClaveMigracion(d.campo(1),
                                                d.campo(11),        // NATC: 9 = sobregiro
                                                d.campo(15)),       // SUMPAN
                        (a, b) -> b));
    }

    Optional<ClaveMigracion> clave(int cveTran) { return Optional.ofNullable(claves.get(cveTran)); }
}

@Bean
Step migra(JobRepository repo, PlatformTransactionManager tx,
           ItemStreamReader<MovimientoS500> movs,            // A01-MOVS500
           MovimientoMigracionRouter router) {
    return new StepBuilder("migra", repo)
            .<MovimientoS500, MovimientoS500>chunk(20_000, tx)   // 461000-VALIDA-END-TRANS
            .reader(movs)
            .writer(router)
            .build();
}

/** El lector guarda su posición en el ExecutionContext: sustituye a CTLP199 y al SEEK. */
class MovimientosS500Reader extends AbstractItemCountingItemStreamItemReader<MovimientoS500> {
    @Override
    protected void jumpToItem(int itemIndex) {
        // W77-NUMREG-MOV500 = W77-AUT-MIGS500 + 1; SEEK A01-MOVS500 RECORD
        archivo.posiciona(itemIndex + 1);
    }
    // doRead(): READ A01-MOVS500 INTO A00-R01-REGMOV AT END -> null
}

@Component
@RequiredArgsConstructor
class MovimientoMigracionRouter implements ItemWriter<MovimientoS500> {

    private final AltaMigracionHandler altas;           // 462000-VALIDA-MIG
    private final CancelacionMigracionHandler bajas;    // 464000-CANCELA y función 2

    @Override
    public void write(Chunk<? extends MovimientoS500> chunk) {
        for (MovimientoS500 m : chunk) {
            switch (m.funcion()) {
                case 21, 22 -> bajas.porProceso(m);               // sin filtro de sucursal: está comentado
                case 2      -> bajas.porAutorizacion(m.autAElimS151());
                default     -> altas.registra(m);                 // la función 1 se filtra adentro
            }
        }
        // Al cerrar el chunk: END-TRANSACTION AUDIT, REWRITE de CTLP199 y BEGIN-TRANSACTION.
    }
}

# application.yml  (antes: WKS-CAT-SUC VALUE 342 y WKS-CAT-CAJA VALUE 36)
p199:
  filtro:
    sucursal-transaccion: 342
    caja-transaccion: 36

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
class AltaMigracionHandler {

    private final MigracionCaptacionRepository b08;     // S151B08TDMIGCAP
    private final CatalogoClavesMigracion catalogo;
    private final TotalesPorBin totales;
    private final FiltroProperties filtro;

    void registra(MovimientoS500 m) {
        if (m.sucTran() != filtro.sucursalTransaccion() || m.cajaTran() != filtro.cajaTransaccion()) return;
        for (int occ = 1; occ <= 5; occ++) {                         // A00-R01-CVEIMP-OC OCCURS 5
            int clave = m.cveTran(occ);
            if (clave == 0) break;                                   // MOVE 6 TO WKS-NUM-OCURR
            var tarjeta = Tarjeta.de(m.mdaCta());                     // 9(16): BIN 9(06) + cuenta 9(10)
            boolean existe = b08.existe(m.fechaMigracion(), tarjeta.bin(), tarjeta.cuenta(),
                                        m.autS151(), occ);           // FIND FIRST B08SXFECTAR
            if (m.funcion() == 1 && !existe && catalogo.clave(clave).isPresent()) {
                b08.save(MigracionCaptacion.activa(m, occ));          // STATUS "AC"
                totales.suma(tarjeta.bin(), catalogo.clave(clave).get(), m.importe(occ));
            }
        }
    }
}

/** Tabla WKS-CVES-BIN: hasta 10 BIN con contadores CEROS, CON ABONO y SOBREGIRO. */
@Component
class TotalesPorBin {

    private static final int MAX_BINS = 10;                  // p199.totales.max-bins
    private final Map<String, Totales> porBin = new LinkedHashMap<>();

    /** 462258-RESTA-A-SDO. La naturaleza debe salir de la clave del registro cancelado. */
    void resta(String bin, ClaveMigracion claveDelRegistro, BigDecimal importe) {
        Totales t = porBin.get(bin);
        if (t == null) return;                               // AT END NEXT SENTENCE
        if (importe.signum() == 0) {
            t.ceros().decrementa();
        } else if (claveDelRegistro.naturaleza() == 9) {
            t.sobregiro().resta(importe);                    // admite negativo, a diferencia del PIC 9(16)V99
        } else {
            t.conAbono().resta(importe);
        }
    }
}

@Component
@RequiredArgsConstructor
class CancelacionMigracionHandler {

    private final MigracionCaptacionRepository b08;
    private final TotalesPorBin totales;
    private final CatalogoClavesMigracion catalogo;

    @Transactional
    void porProceso(MovimientoS500 m) {
        Stream<MigracionCaptacion> afectados = (m.funcion() == 21)
                ? b08.lockByFechaYProceso(m.fechaMigracion(), m.tipoProceso())          // B08SXFECNUMPRO
                : b08.lockByFechaAutDesdeYProceso(m.fechaMigracion(),
                                                  m.autAElimS151(),                   // AUT >= AELIM
                                                  m.tipoProceso());                   // B08SXFECAUT
        afectados.forEach(r -> {
            // El fuente no filtra por status: un registro ya "CA" se vuelve a restar.
            if (r.estaActivo()) {
                r.cancela();                                                         // STATUS "CA"
                totales.resta(r.bin(), catalogo.clave(r.cveTrans()).orElseThrow(), r.importe());
            }
        });
    }
}

/** 703000-STORE-B08. */
boolean guarda(MigracionCaptacion r) {
    try {
        b08.saveAndFlush(r);
        return true;
    } catch (DataIntegrityViolationException dup) {         // DMSTATUS (DUPLICATES)
        log.warn("REG DUPLICADO B08 ,CTO={} ,SUC={} ,CTA={} ,AUT={} ,OCC={}",
                 r.contrato(), r.mdaSuc(), r.mdaTarjeta(), r.autS151(), r.numOcurrs());
        return false;                                        // W77-DUP-B08 = 1: no suma totales
    }
    // cualquier otra excepción se propaga y falla el step (801000-DMTERMINATE)
}
